document.querySelectorAll('.password-toggle').forEach(button=>button.addEventListener('click',()=>{const input=button.parentElement.querySelector('input');const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide':'Show';button.setAttribute('aria-label',show?'Hide password':'Show password')}));
const password=document.querySelector('#password');const meter=document.querySelector('.password-meter');password?.addEventListener('input',()=>{const value=password.value;const score=[value.length>=8,/[A-Z]/.test(value),/[0-9]/.test(value),/[^A-Za-z0-9]/.test(value)].filter(Boolean).length;meter.className='password-meter'+(score>=4?' strong':score>=2?' medium':'')});
document.querySelector('.auth-form')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const match=form.querySelector('#confirm-password');if(match&&match.value!==password.value){match.setCustomValidity('Passwords do not match');match.reportValidity();match.addEventListener('input',()=>match.setCustomValidity(''),{once:true});return}const message=form.querySelector('.auth-message');message.textContent=form.dataset.mode==='signup'?'Design preview complete. Account creation will be connected when the authentication backend is ready.':'Design preview complete. Login will be enabled when the authentication backend is connected.';message.classList.add('show')});
